-- Palindrome Check (Easy)
INSERT INTO coding_problems (slug, title, description, difficulty, category, type, tags, starter_code, test_cases, examples, constraints, points, order_index, time_limit_ms, memory_limit_kb, input_format, output_format, editorial, judged)
VALUES ($q$palindrome-check$q$, $q$Palindrome Check$q$, $q$A phrase is a palindrome if, after ignoring every character that is not a letter or a digit and ignoring the difference between upper and lower case, it reads the same forwards and backwards.

Decide whether the given line is a palindrome. A line with no letters or digits counts as a palindrome.$q$, $q$Easy$q$, $q$Strings$q$, 'code', ARRAY[$q$string$q$, $q$two-pointers$q$]::text[], $q${"python": "import sys\n\n\ndef main():\n    lines = sys.stdin.read().split('\\n')\n    # Input:\n    # One line of ASCII text. It may be empty.\n    # TODO: solve, then print the answer\n\n\nmain()\n", "javascript": "const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\n// Input:\n// One line of ASCII text. It may be empty.\n// TODO: solve, then console.log the answer\n", "java": "import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n        List<String> lines = new ArrayList<>();\n        for (String s; (s = in.readLine()) != null; ) lines.add(s);\n        // Input:\n        // One line of ASCII text. It may be empty.\n        // TODO: solve, then System.out.println the answer\n    }\n}\n", "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // Input:\n    // One line of ASCII text. It may be empty.\n    // TODO: read with cin / getline, solve, print the answer\n    return 0;\n}\n", "c": "#include <stdio.h>\n\nint main(void) {\n    // Input:\n    // One line of ASCII text. It may be empty.\n    /* TODO: read with scanf / fgets, solve, print the answer */\n    return 0;\n}\n"}$q$::jsonb, '[]'::jsonb, $q$[{"input": "A man, a plan, a canal: Panama", "output": "YES", "explanation": "Filtered and lowercased: amanaplanacanalpanama."}, {"input": "race a car", "output": "NO", "explanation": "Filtered: raceacar."}]$q$::jsonb, ARRAY[$q$0 ≤ length ≤ 30 000$q$, $q$ASCII characters only$q$]::text[], 10, 1004, 2000, 262144, $q$One line of ASCII text. It may be empty.$q$, $q$YES or NO.$q$, $q$Use two pointers from both ends. Skip characters that are not alphanumeric, then compare the lowercased characters. Stop at the first mismatch. O(n) time, O(1) extra space.$q$, false)
ON CONFLICT (slug) DO NOTHING;

